ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+shadows/i)
  OR (ImageFileName=/\\wmic\.exe$/i AND CommandLine=/shadowcopy\s+delete/i)
  OR (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)/i)
  OR (ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/delete\s+catalog/i)
  OR (ImageFileName=/\\(net|sc|taskkill)\.exe$/i AND CommandLine=/(veeam|mssql|sqlwriter|memtas|sophos|windefend|msmpeng|securityhealthservice|backup)/i)
| case {
    ImageFileName=/\\(vssadmin|wmic)\.exe$/i | Technique := "ShadowDelete";
    ImageFileName=/\\bcdedit\.exe$/i         | Technique := "RecoveryDisable";
    ImageFileName=/\\wbadmin\.exe$/i         | Technique := "BackupCatalogDelete";
    *                                         | Technique := "ServiceStop";
  }
| bucket(span=10m, field=@timestamp)
| groupBy([aid, ComputerName, UserName, _bucket], function=[count(as=Events), collect(Technique, as=Techniques), collect(CommandLine, limit=5, as=SampleCmds)])
| TechniqueCount := length("Techniques")
| TechniqueCount >= 2
| sort(_bucket, order=desc)

#event_simpleName=ProcessRollup2
| ParentBaseFileName=/^(remote access|simpleservice|simplehelpcustomer|jwrapper-remote access|simplegatewayservice)\.exe$/i OR regex("\\\\(SimpleHelp|JWrapper-Remote Access|Remote Access)\\\\", field=ParentImageFileName)
| ImageFileName=/\\(cmd|powershell|pwsh|nltest|net1?|whoami|quser|systeminfo|tasklist|ipconfig|arp|route|hostname|qwinsta|procdump|reg|adfind|advanced_ip_scanner|netscan|mimikatz|rundll32)\.exe$/i
| case {
    ImageFileName=/\\(nltest|net1?|whoami|quser|systeminfo|tasklist|ipconfig|arp|route|hostname|qwinsta)\.exe$/i | Category := "Recon";
    ImageFileName=/\\(procdump|adfind|advanced_ip_scanner|netscan|mimikatz)\.exe$/i | Category := "CredOrTool";
    ImageFileName=/\\rundll32\.exe$/i AND CommandLine=/comsvcs/i                    | Category := "CredOrTool";
    ImageFileName=/\\(cmd|powershell|pwsh)\.exe$/i                                   | Category := "Shell";
    *                                                                                | Category := "Other";
  }
| Category != "Other"
| bucket(span=15m, field=@timestamp)
| groupBy([aid, ComputerName, UserName, _bucket], function=[count(as=Total), collect(Category, as=Categories), collect(ImageFileName, as=Bins), collect(CommandLine, limit=10, as=Cmds)])
| ReconCount := length(regex("Recon", field=Categories, repeat=true))
| CredCount  := length(regex("CredOrTool", field=Categories, repeat=true))
| ShellCount := length(regex("Shell", field=Categories, repeat=true))
| (ReconCount >= 3 AND ShellCount >= 1) OR CredCount >= 1
| sort(_bucket, order=desc)
